    start: allDay ? '' : String(s.dateTime || '').slice(11, 16), end: allDay ? '' : String(en.dateTime || '').slice(11, 16),
    endDate: allDay ? addDays(en.date || s.date, -1) : String(en.dateTime || '').slice(0, 10),
